al_topology = self.config.virtual_topology # Счетчики и время self.cycle_count = 0 self.simulation_time = 0.0 self.start_time = time.time() # Активность и состояния self.activations = np.zeros(self.num_neurons, dtype=np.float32) self.activation_buffer = np.zeros(self.num_neurons, dtype=np.float32) # Инициализация синапсов self._init_synaptic_structure() # Нейромодуляторы (global) self.neuromodulators = np.zeros(4, dtype=np.float16) # DA, 5HT, NE, ACh self.neuromodulators[:] = [0.1, 0.05, 0.1, 0.02] # Ритмы мозга self.brain_rhythms = np.zeros(4, dtype=np.float16) # theta, alpha, beta, gamma # Статистика self.stats = { 'activations_per_cycle': deque(maxlen=100), 'energy_consumption': 0.0, 'criticality': 0.0, 'entropy': 0.0, 'phase_coherence': 0.0 } # GPU acceleration self.gpu_enabled = self.config.use_gpu and self._check_gpu() if self.gpu_enabled: self._init_gpu() self._print_init_info() def _init_synaptic_structure(self): """Инициализация синаптической структуры""" print("🧬 Инициализация синаптической структуры...") if self.virtual_topology: # ВИРТУАЛЬНЫЙ РЕЖИМ (экономия памяти) self._init_virtual_topology() else: # РЕЖИМ С ЯВНЫМИ СВЯЗЯМИ (больше памяти, но быстрее) self._init_explicit_topology() def _init_virtual_topology(self): """Инициализация виртуальной топологии""" # Генерация степеней нейронов (распределение Парето) self.degrees = self._generate_pareto_degrees( self.config.avg_synapses, shape=2.0 ).astype(np.uint32) # Смещения для быстрого доступа self.offsets = np.zeros(self.num_neurons + 1, dtype=np.uint32) self.offsets[1:] = np.cumsum(self.degrees) # Данные синапсов (УЛЬТРА-КОМПАКТНЫЙ ФОРМАТ) total_synapses = self.offsets[-1] # Пакетное хранение: [weight(2bit) | phase(2bit) | plasticity(2bit) | state(2bit)] # 8 бит = 1 байт на синапс self.synapse_data = np.random.randint( 0, 256, total_synapses, dtype=np.uint8 ) # Индекс последней активации (для STDP) self.last_activation = np.zeros(total_synapses, dtype=np.uint8) self.total_synapses = total_synapses print(f" Виртуальная топология: {self.total_synapses:,} синапсов") def _init_explicit_topology(self): """Инициализация явной топологии""" # Генерация графа (предпочтительное присоединение) print(" Построение графа связей...") m0 = 10 m = self.config.avg_synapses # Инициализация первых m0 нейронов edges = [] for i in range(min(m0, self.num_neurons)): for j in range(i + 1, min(m0, self.num_neurons)): edges.append((i, j)) edges.append((j, i)) # Добавление остальных нейронов for new_node in range(m0, self.num_neurons): # Выбор существующих нейронов для соединения targets = np.random.choice( new_node, size=min(m, new_node), replace=False ) for target in targets: edges.append((new_node, target)) edges.append((target, new_node)) # Преобразование в CSR формат self.edges = np.array(edges, dtype=np.uint32) self.total_synapses = len(edges) # Данные синапсов self.weights = np.random.uniform(0.1, 0.9, self.total_synapses).astype(np.float16) self.phases = np.random.randint(0, 256, self.total_synapses, dtype=np.uint8) print(f" Явная топология: {self.total_synapses:,} синапсов") def _generate_pareto_degrees(self, scale, shape): """Генерация степеней по распределению Парето (как в мозге)""" degrees = np.random.pareto(shape, self.num_neurons) * scale + 1 degrees = np.clip(degrees, 1, 1000).astype(np.uint32) return degrees def _check_gpu(self): """Проверка доступности GPU""" try: import cupy return True except ImportError: try: import numba.cuda return numba.cuda.is_available() except: return False return False def _init_gpu(self): """Инициализация GPU""" print("🚀 Инициализация GPU ускорения...") try: import cupy as cp self.gpu = cp # Перенос данных на GPU self.activations_gpu = cp.asarray(self.activations) self.activation_buffer_gpu = cp.asarray(self.activation_buffer) if hasattr(self, 'weights'): self.weights_gpu = cp.asarray(self.weights) self.phases_gpu = cp.asarray(self.phases) print(" GPU ускорение активировано") except Exception as e: print(f" GPU недоступно: {e}") self.gpu_enabled =